// crates/flint-render/src/ocean_pipeline.rs
//! Gerstner ocean rendering pipeline.
//!
//! One static grid mesh — normalized [-1,1]² coordinates, radially warped in
//! the vertex shader so the center is dense and the rim reaches kilometers —
//! follows the camera via a snapped `grid_offset` uniform. Vertices displace
//! with the wave array generated by `flint_geometry::ocean::WaveSpectrum` (the
//! CPU/GPU parity keystone: the GPU only sums what the CPU generated).
//!
//! Bind groups: 0 = transforms (shared), 1 = OceanUniforms + a water body's
//! look (ADR 0094), 2 = lights + shadows (shared), 3 = the refraction
//! grab-pass. Lakes and rivers draw with `body_pipeline`: the same shading
//! on a supplied mesh (see `water_body.rs`).

use crate::gpu_counts::CountedDevice;
use crate::TrustedShader;
use bytemuck::{Pod, Zeroable};
use flint_geometry::ocean::MAX_WAVES;

/// Grid resolution (cells per side). 256 → 66k vertices, ~0.5 MB.
pub const OCEAN_GRID_CELLS: u32 = 256;

/// Uniform block — layout must match `OceanUniforms` in ocean_shader.wgsl.
#[repr(C)]
#[derive(Copy, Clone, Debug, Pod, Zeroable)]
pub struct OceanUniformsGpu {
    /// Two vec4 per wave: [dir.x, dir.y, k, amp], [phase_t, q, 0, 0].
    pub waves: [[f32; 4]; MAX_WAVES * 2],
    pub deep_color: [f32; 4],
    pub shallow_color: [f32; 4],
    pub foam_color: [f32; 4],
    pub sss_color: [f32; 4],
    pub grid_offset: [f32; 2],
    pub num_waves: u32,
    pub enable_tonemapping: u32,
    pub grid_scale: f32,
    pub fade_start: f32,
    pub fade_end: f32,
    pub foam_threshold: f32,
    pub foam_noise_scale: f32,
    pub ramp_steps: f32,
    pub specular_strength: f32,
    pub time: f32,
    // ── Refraction / turbidity (grab pass) ──
    pub absorption_color: [f32; 3],
    pub turbidity: f32,
    pub refraction_strength: f32,
    pub camera_near: f32,
    pub camera_far: f32,
    /// 1 when the grab pass ran this frame (scene color/depth are valid).
    pub grab_enabled: u32,
    /// Sky gradient snapshot for analytic reflections (from the `sky`
    /// component; strength 0 when the scene has no procedural sky).
    pub sky_zenith: [f32; 4],
    pub sky_horizon: [f32; 4],
    pub sky_haze: [f32; 4],
    pub sky_reflection_strength: f32,
    // ── Contact foam (a splash ring round each `ocean_contact` hull) ──
    /// Overall gain; forced 0 when the scene has no contact entity.
    pub splash_strength: f32,
    /// Max foam band width outward from the hull at full churn (m).
    pub splash_width: f32,
    /// Lapping-animation rate.
    pub splash_flicker_speed: f32,
    /// Churn floor on calm water.
    pub splash_baseline: f32,
    /// World-space frequency of the scalloped edge.
    pub splash_noise_scale: f32,
    /// Impact speed to churn gain (s/m).
    pub splash_response: f32,
    /// How many of `hulls` are in use (0..=`MAX_CONTACTS`).
    pub contact_count: u32,
    // ── Cel band edge treatment ──
    /// Noise wobble amplitude on the diffuse ramp, in shade units (0 = off).
    pub band_wobble: f32,
    /// Halftone transition width at band edges (0 = hard line, 1 = full band).
    pub band_dither: f32,
    /// World-space halftone dot grid frequency (dots per meter).
    pub band_dither_scale: f32,
    /// Rain impact-ring density 0..1 (0 = off).
    pub rain_ripple: f32,
    // ── Bioluminescent foam ──
    /// Emissive glow rgb + strength in .a (0 = off).
    pub foam_glow: [f32; 4],
    // ── Tint (#746: was render modes 2 and 5's remap) ──
    /// How far the palette moves to the tint's, 0..1 (0 = off).
    pub tint: f32,
    /// [`TINT_BELOW`] | [`TINT_KEEP_LIGHT`].
    pub tint_flags: u32,
    // ── Shoreline foam (from the grab pass's depth) ──
    /// Band width in metres of water depth below the surface (0 = off).
    pub shore_foam_width: f32,
    /// Opacity gain of the shoreline band.
    pub shore_foam_strength: f32,
    /// Shoreline foam colour (RGBA linear).
    pub shore_foam_color: [f32; 4],
    /// Lapping rate of the shoreline band.
    pub shore_foam_speed: f32,
    /// Highest a solid may stand above the surface and still be the shore
    /// the screen-space search measures to (0 = no search).
    pub shore_foam_reach: f32,
    pub _pad_shore: [f32; 2],
    /// The tint's palette (#746): deep rgb + pool scale, shallow rgb +
    /// band count (0 = keep), sss rgb + band wobble added, foam rgb (shore
    /// foam too) + spare, the reflections' rgb multiplier + spare.
    pub tint_deep: [f32; 4],
    pub tint_shallow: [f32; 4],
    pub tint_sss: [f32; 4],
    pub tint_foam: [f32; 4],
    pub tint_sky: [f32; 4],
    /// The hulls the sea foams round this frame, the first `contact_count`
    /// of them (#749).
    pub hulls: [ContactHullGpu; MAX_CONTACTS],
}

/// [`OceanUniformsGpu::tint_flags`]: tint only the surface seen from
/// below (the ceiling over a submerged eye).
pub const TINT_BELOW: u32 = 1;
/// [`OceanUniformsGpu::tint_flags`]: scale the tint's deep and shallow by
/// the palette's own brightness, so a night sea stays dark.
pub const TINT_KEEP_LIGHT: u32 = 2;

/// A tint the sea's palette moves toward (#746): the `ocean` component's
/// `tint*` fields, which a game drives (a storm greying the sea, a dye
/// spreading in pools, the surface seen from below). It was two looks of
/// one game in the ocean shader; now it is one general recolour with named
/// settings. Applied to the palette before any use, so
/// bands, subsurface, foam and reflections agree, and after a script's
/// palette lands, so it can't race one.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct OceanTint {
    /// How far the palette moves to the tint's, 0..1. With `pools` above
    /// 0 it is also how much of the sea the pools cover.
    pub amount: f32,
    pub deep: [f32; 3],
    pub shallow: [f32; 3],
    pub sss: [f32; 3],
    /// The foam's, and the shore foam's.
    pub foam: [f32; 3],
    /// What the sky's reflection is multiplied by.
    pub sky: [f32; 3],
    /// The cel bands the tinted water takes (0 = the sea's own).
    pub ramp_steps: f32,
    /// Added to the bands' wobble where tinted.
    pub band_wobble: f32,
    /// World-anchored pools, this many per metre (the fbm's frequency),
    /// spreading to full cover as `amount` rises; 0 tints evenly.
    pub pools: f32,
    /// Scale deep and shallow by the palette's own brightness.
    pub keep_light: bool,
    /// Only the surface seen from below.
    pub below: bool,
}

/// The default sea's palette (bold flat blues per the stylized
/// references): `OceanVisuals`' and so the `ocean` schema's defaults, and
/// the palette a default tint moves toward.
const SEA_DEEP: [f32; 4] = [0.055, 0.22, 0.53, 1.0];
const SEA_SHALLOW: [f32; 4] = [0.16, 0.51, 0.83, 1.0];
const SEA_FOAM: [f32; 4] = [0.96, 0.99, 1.0, 1.0];
const SEA_SSS: [f32; 4] = [0.10, 0.75, 0.75, 1.0];

const fn rgb(c: [f32; 4]) -> [f32; 3] {
    [c[0], c[1], c[2]]
}

impl Default for OceanTint {
    /// Off, and a palette that is the default sea's own: a tint names the
    /// colours it moves toward, so one that names none changes nothing
    /// however far it goes (#1041).
    fn default() -> Self {
        Self {
            amount: 0.0,
            deep: rgb(SEA_DEEP),
            shallow: rgb(SEA_SHALLOW),
            sss: rgb(SEA_SSS),
            foam: rgb(SEA_FOAM),
            sky: [1.0, 1.0, 1.0],
            ramp_steps: 0.0,
            band_wobble: 0.0,
            pools: 0.0,
            keep_light: false,
            below: false,
        }
    }
}

impl OceanTint {
    /// A sea of blood: pools that spread with `amount`, night-dark,
    /// viscous (two wobbling bands). One of the presets `tint_preset` names.
    pub fn blood(amount: f32) -> Self {
        Self {
            amount,
            deep: [0.10, 0.005, 0.01],
            shallow: [0.45, 0.04, 0.05],
            sss: [0.85, 0.05, 0.03],
            foam: [0.95, 0.78, 0.76],
            sky: [1.1, 0.3, 0.32],
            ramp_steps: 2.0,
            band_wobble: 0.15,
            pools: 0.08,
            keep_light: true,
            below: false,
        }
    }

    /// The surface seen from under it: murk blues and flat white foam
    /// panes on the underside only, two bands. One of the presets
    /// `tint_preset` names.
    pub fn underside(amount: f32) -> Self {
        Self {
            amount,
            deep: [0.02, 0.12, 0.26],
            shallow: [0.07, 0.30, 0.46],
            sss: [0.10, 0.45, 0.55],
            foam: [0.94, 0.98, 1.0],
            sky: [1.0, 1.0, 1.0],
            ramp_steps: 2.0,
            band_wobble: 0.0,
            pools: 0.0,
            keep_light: false,
            below: true,
        }
    }

    /// The presets `tint_preset` names, in the schema's order.
    pub const PRESETS: [&'static str; 2] = ["blood", "underside"];

    /// A preset by name at `amount`: `blood` or `underside` (#1035).
    pub fn preset(name: &str, amount: f32) -> Option<Self> {
        match name {
            "blood" => Some(Self::blood(amount)),
            "underside" => Some(Self::underside(amount)),
            _ => None,
        }
    }

    /// The tint from an `ocean` component's `tint*` fields, each falling
    /// back on the preset `tint_preset` names, so a script switches between
    /// two tints with one string (#1035) and a written field still wins
    /// over its preset. With no preset (#1041) a tint names the colours it
    /// moves toward: one it leaves out is the component's own (its
    /// `deep_color`...) and every other setting changes nothing, so `tint`
    /// alone moves the sea toward itself. Read through the typed view (ADR
    /// 0115): a wrong type or an unknown preset reads as the default and is
    /// reported once.
    pub fn from_component(view: &flint_ecs::ComponentView<'_>) -> Self {
        let preset = view
            .opt_choice("tint_preset", &Self::PRESETS)
            .and_then(|name| Self::preset(name, 0.0));
        let d = preset.unwrap_or_default();
        let f = |name: &str, dv: f32| view.f32(name, dv);
        let c = |name: &str, dv: [f32; 3]| {
            let c = view.color(name, [dv[0], dv[1], dv[2], 1.0]);
            [c[0], c[1], c[2]]
        };
        let b = |name: &str, dv: bool| view.bool(name, dv);
        // A preset names its colours; with none, the sea's own stand in
        let own = |sea_field: &str, dv: [f32; 3]| {
            if preset.is_some() {
                dv
            } else {
                c(sea_field, dv)
            }
        };
        Self {
            amount: f("tint", d.amount).clamp(0.0, 1.0),
            deep: c("tint_deep_color", own("deep_color", d.deep)),
            shallow: c("tint_shallow_color", own("shallow_color", d.shallow)),
            sss: c("tint_sss_color", own("sss_color", d.sss)),
            foam: c("tint_foam_color", own("foam_color", d.foam)),
            sky: c("tint_sky", d.sky),
            ramp_steps: f("tint_ramp_steps", d.ramp_steps).clamp(0.0, 8.0),
            band_wobble: f("tint_band_wobble", d.band_wobble).clamp(0.0, 1.0),
            pools: f("tint_pools", d.pools).clamp(0.0, 4.0),
            keep_light: b("tint_keep_light", d.keep_light),
            below: b("tint_below", d.below),
        }
    }

    /// Its share of the uniform: (amount, flags, deep, shallow, sss,
    /// foam, sky).
    pub(crate) fn to_gpu(self) -> (f32, u32, [[f32; 4]; 5]) {
        let row = |c: [f32; 3], w: f32| [c[0], c[1], c[2], w];
        let flags = if self.below { TINT_BELOW } else { 0 }
            | if self.keep_light { TINT_KEEP_LIGHT } else { 0 };
        (
            self.amount.clamp(0.0, 1.0),
            flags,
            [
                row(self.deep, self.pools),
                row(self.shallow, self.ramp_steps),
                row(self.sss, self.band_wobble),
                row(self.foam, 0.0),
                row(self.sky, 0.0),
            ],
        )
    }
}

/// How many `ocean_contact` hulls foam at once. Past this the ones nearest
/// the camera foam, and each one left out is warned about once by name.
pub const MAX_CONTACTS: usize = 4;

/// One contact hull, laid out as `ContactHull` in ocean_shader.wgsl.
#[repr(C)]
#[derive(Copy, Clone, Debug, Default, PartialEq, Pod, Zeroable)]
pub struct ContactHullGpu {
    /// [center.x, center.z, cos(yaw), sin(yaw)], the hull as drawn.
    pub pose: [f32; 4],
    /// [half_x, half_z, 0, 0] in metres, the world scale applied.
    pub extent: [f32; 4],
    /// [vel.x, vel.y, vel.z, 0] in m/s, the hull's own motion.
    pub velocity: [f32; 4],
}

/// Visual (non-simulation) parameters of the `ocean` component.
/// Simulation params live in `flint_geometry::ocean::OceanParams`.
#[derive(Debug, Clone, PartialEq)]
pub struct OceanVisuals {
    pub deep_color: [f32; 4],
    pub shallow_color: [f32; 4],
    pub foam_color: [f32; 4],
    pub sss_color: [f32; 4],
    pub grid_scale: f32,
    pub fade_start: f32,
    pub fade_end: f32,
    pub foam_threshold: f32,
    pub foam_noise_scale: f32,
    pub ramp_steps: f32,
    pub specular_strength: f32,
    /// Water cloudiness: 0 = glass-clear, higher = murk sooner (1/m-ish).
    pub turbidity: f32,
    /// Screen-space refraction distortion strength.
    pub refraction_strength: f32,
    /// Per-channel absorption tint (red absorbs first in seawater).
    pub absorption_color: [f32; 3],
    /// Fresnel-weighted analytic sky reflection amount (0 disables).
    pub sky_reflection_strength: f32,
    /// Contact foam overall gain (0 disables).
    pub splash_strength: f32,
    /// Max contact foam band width at full churn (m).
    pub splash_width: f32,
    /// Contact foam lapping/flicker animation rate.
    pub splash_flicker_speed: f32,
    /// World-space frequency of the contact foam scalloped edge.
    pub splash_noise_scale: f32,
    /// Churn floor on calm water (0 = foam vanishes when flat).
    pub splash_baseline: f32,
    /// Impact speed → churn gain (s/m).
    pub splash_response: f32,
    /// Cel ramp edge wobble amplitude (0 = razor band contours).
    pub band_wobble: f32,
    /// Halftone dither width at band edges (0 = hard line).
    pub band_dither: f32,
    /// Halftone dot grid frequency (dots per meter).
    pub band_dither_scale: f32,
    /// Rain impact-ring density (0 = none). A game's weather sets it.
    pub rain_ripple: f32,
    /// Bioluminescent foam glow color (emissive; unlit by design: it IS a
    /// light source).
    pub foam_glow_color: [f32; 4],
    /// Bioluminescent glow strength (0 = off). A game's clock sets it.
    pub foam_glow: f32,
    /// Shoreline foam band: where the opaque scene behind the water lies
    /// within this many metres below the surface (0 = off, the default).
    pub shore_foam_width: f32,
    /// Shoreline foam opacity gain.
    pub shore_foam_strength: f32,
    /// Shoreline foam lapping rate (0 = still).
    pub shore_foam_speed: f32,
    /// Shoreline foam colour (RGBA linear).
    pub shore_foam_color: [f32; 4],
    /// Screen-space shore search (ADR 0091): a solid on screen standing up
    /// to this many metres above the surface is the shore, and the band is
    /// measured across the water to it, so it keeps its width from any
    /// angle. 0 = off: depth along the view ray only (ADR 0088).
    pub shore_foam_reach: f32,
    /// The palette's tint (#746), off at amount 0.
    pub tint: OceanTint,
}

